/**
 * The Shop's data layer: an affiliate aggregator in Peptaura's shape.
 *
 * Compound-first: a catalog of compounds, each with one row per vendor that
 * stocks it, ranked in the vendor research pipeline's order ("Recommended").
 * Vendors are ranked, never graded, on the site: the tier letters and scores
 * in the app catalog are read only to order the rows.
 *
 * Data is generated by `scripts/build-shop-data.mjs` from the app repo's
 * vendor research and the live product pulls; never hand-edit the JSON.
 */
import vendorsRaw from "./data/shop-vendors.json";
import offersRaw from "./data/shop-offers.json";
import compoundsRaw from "./data/shop-compounds.json";
import coasRaw from "./data/shop-coas.json";
import labsRaw from "./data/shop-labs.json";
import { dashesToCommas } from "./library";

export interface Coa {
  vendorSlug: string;
  vendorName: string;
  productName: string | null;
  compoundSlug: string | null;
  batch: string | null;
  lab: string | null;
  method: string | null;
  purity: number | null;
  netContentMg: number | null;
  vialsTested: number | null;
  date: string | null;
  pdf: string | null;
}

export interface Lab {
  name: string;
  detail: string | null;
  vendors: string[];
  coaCount: number;
}

export interface CoaExample {
  productName: string | null;
  batchNumber: string | null;
  labName: string | null;
  testMethod: string | null;
  purityPercent: number | null;
  netContentMg: number | null;
  vialsTested: number | null;
  testDate: string | null;
  coaPdf: string | null;
}

export interface ShopVendor {
  slug: string;
  name: string;
  domain: string | null;
  url: string | null;
  /** Discount code the vendor honours for REGEN readers, if any. */
  code: string | null;
  country: string | null;
  location: string | null;
  logoUrl: string | null;
  tagline: string | null;
  summary: string | null;
  differentiator: string | null;
  standoutPro: string | null;
  standoutCon: string | null;
  verdict: string | null;
  labs: string[] | null;
  testingScope: string[] | null;
  coaArchive: boolean | null;
  coaCount: number | null;
  coaAvgPurity: number | null;
  independentlyTested: boolean | null;
  contaminantTrifecta: boolean | null;
  legalEntity: string | null;
  founderNamed: boolean | null;
  strengthTags: string[] | null;
  watchoutTags: string[] | null;
  trustpilotCount: number | null;
  trustpilotAverage: number | null;
  skuCount: number | null;
  domainAgeMonths: number | null;
  researchStatus: string | null;
  verification: string | null;
  xHandle: string | null;
  rank: number;
  score: number | null;
  coaExamples: CoaExample[];
  incidents: { date?: string; text?: string; summary?: string; source?: string }[];
}

export interface Variant {
  label: string | null;
  sizeMg: number | null;
  /** Vials in the pack. Null when the store sells a multi-vial pack without
   *  saying how many; such a pack shows a price but no price per mg. */
  quantity: number | null;
  priceUsd: number;
  available: boolean | null;
}

/** "1 vial", "10 vials", or "Pack" when the count is not known. */
export function packLabel(v: Variant): string {
  if (v.quantity === null) return "Pack";
  return v.quantity > 1 ? `${v.quantity} vials` : "1 vial";
}

export interface Offer {
  compoundSlug: string;
  vendorSlug: string;
  productName: string;
  productUrl: string;
  currency: "USD" | "AUD";
  fetchedAt: string | null;
  variants: Variant[];
}

export interface ShopCompound {
  slug: string;
  name: string;
  kind: "compound" | "blend" | "essential";
  vendorCount: number;
  variantCount: number;
  sizesMg: number[];
  minUsdPerMg: number | null;
  /** Library guide slug when the compound has a page. */
  guideSlug: string | null;
}

/* ---- Load (cleaned once) --------------------------------------------------- */

const clean = (s: string | null) => (s ? dashesToCommas(s) : s);

export const SHOP_VENDORS: ShopVendor[] = (vendorsRaw as ShopVendor[])
  .map((v) => ({
    ...v,
    tagline: clean(v.tagline),
    summary: clean(v.summary),
    differentiator: clean(v.differentiator),
    standoutPro: clean(v.standoutPro),
    standoutCon: clean(v.standoutCon),
    verdict: clean(v.verdict),
    location: clean(v.location),
    testingScope: v.testingScope?.map((t) => dashesToCommas(t)) ?? null,
    incidents: (v.incidents ?? []).map((i) => ({ ...i, text: i.text ? dashesToCommas(i.text) : i.text })),
  }))
  .sort((a, b) => a.rank - b.rank);

export const SHOP_OFFERS: Offer[] = offersRaw as Offer[];
export const SHOP_COMPOUNDS: ShopCompound[] = compoundsRaw as ShopCompound[];
export const SHOP_COAS: Coa[] = (coasRaw as Coa[]).map((c) => ({ ...c, method: c.method ? dashesToCommas(c.method) : c.method }));
export const SHOP_LABS: Lab[] = labsRaw as Lab[];

const normBatch = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");

/** Batch lookup for /shop/verify: exact after normalisation, then a
 *  contained match so a partially typed batch still finds its certificate. */
export function findBatch(query: string): Coa[] {
  const q = normBatch(query);
  if (q.length < 4) return [];
  const exact = SHOP_COAS.filter((c) => c.batch && normBatch(c.batch) === q);
  if (exact.length) return exact;
  return SHOP_COAS.filter((c) => c.batch && normBatch(c.batch).includes(q)).slice(0, 10);
}

export function labBySlug(slug: string): Lab | undefined {
  return SHOP_LABS.find((l) => labSlug(l.name) === slug);
}

export function labSlug(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

const VENDOR_BY_SLUG = new Map(SHOP_VENDORS.map((v) => [v.slug, v]));
const COMPOUND_BY_SLUG = new Map(SHOP_COMPOUNDS.map((c) => [c.slug, c]));
const OFFERS_BY_COMPOUND = new Map<string, Offer[]>();
for (const o of SHOP_OFFERS) {
  if (!OFFERS_BY_COMPOUND.has(o.compoundSlug)) OFFERS_BY_COMPOUND.set(o.compoundSlug, []);
  OFFERS_BY_COMPOUND.get(o.compoundSlug)!.push(o);
}
const OFFERS_BY_VENDOR = new Map<string, Offer[]>();
for (const o of SHOP_OFFERS) {
  if (!OFFERS_BY_VENDOR.has(o.vendorSlug)) OFFERS_BY_VENDOR.set(o.vendorSlug, []);
  OFFERS_BY_VENDOR.get(o.vendorSlug)!.push(o);
}

export function vendorBySlug(slug: string): ShopVendor | undefined {
  return VENDOR_BY_SLUG.get(slug);
}

export function compoundBySlug(slug: string): ShopCompound | undefined {
  return COMPOUND_BY_SLUG.get(slug);
}

export function shopHref(compoundSlug: string): string {
  return `/shop/${compoundSlug}`;
}

export function vendorHref(vendorSlug: string): string {
  return `/shop/vendors/${vendorSlug}`;
}

/** Vendors with a live catalog on the site. */
export function vendorsWithOffers(): ShopVendor[] {
  return SHOP_VENDORS.filter((v) => OFFERS_BY_VENDOR.has(v.slug));
}

/* ---- Offer rows -------------------------------------------------------------- */

export interface OfferRow {
  vendorSlug: string;
  vendorName: string;
  logoUrl: string | null;
  rank: number;
  country: string | null;
  code: string | null;
  independentlyTested: boolean;
  coaArchive: boolean;
  labs: string[];
  purity: number | null;
  productName: string;
  productUrl: string;
  currency: "USD" | "AUD";
  variants: Variant[];
  latestCoa: { date: string | null; pdf: string | null; lab: string | null; batch: string | null } | null;
}

const norm = (s: string) => s.toLowerCase().replace(/\(.*?\)/g, "").replace(/[^a-z0-9]+/g, " ").trim();

/** The vendor's most recent COA whose product name names this compound. */
export function latestCoaFor(vendor: ShopVendor, compoundName: string): OfferRow["latestCoa"] {
  const key = norm(compoundName).split(" ")[0];
  if (!key) return null;
  const hits = vendor.coaExamples
    .filter((c) => c.productName && norm(c.productName).includes(key))
    .sort((a, b) => String(b.testDate ?? "").localeCompare(String(a.testDate ?? "")));
  const c = hits[0];
  return c ? { date: c.testDate, pdf: c.coaPdf, lab: c.labName, batch: c.batchNumber } : null;
}

/**
 * One row per VENDOR for the compound, in Recommended order. A vendor that
 * lists the compound as several products (sizes, pack counts) gets one card
 * with every pack inside it, the way the reference draws it; a card per
 * product put the same vendor on the page three times.
 */
export function offerRowsFor(compound: ShopCompound): OfferRow[] {
  const list = OFFERS_BY_COMPOUND.get(compound.slug) ?? [];
  const byVendor = new Map<string, OfferRow>();
  for (const o of list) {
    const v = VENDOR_BY_SLUG.get(o.vendorSlug);
    if (!v) continue;
    let row = byVendor.get(v.slug);
    if (!row) {
      row = {
        vendorSlug: v.slug,
        vendorName: v.name,
        logoUrl: v.logoUrl,
        rank: v.rank,
        country: v.country,
        code: v.code,
        independentlyTested: Boolean(v.independentlyTested),
        coaArchive: Boolean(v.coaArchive),
        labs: v.labs ?? [],
        purity: v.coaAvgPurity,
        productName: o.productName,
        productUrl: o.productUrl,
        currency: o.currency,
        variants: [],
        latestCoa: latestCoaFor(v, compound.name),
      };
      byVendor.set(v.slug, row);
    }
    for (const x of o.variants) {
      const dup = row.variants.some((y) => y.sizeMg === x.sizeMg && y.quantity === x.quantity && y.priceUsd === x.priceUsd);
      if (!dup) row.variants.push({ ...x, label: x.label ?? o.productName });
    }
  }
  for (const row of byVendor.values()) {
    row.variants.sort(
      (a, b) => (a.sizeMg ?? 0) - (b.sizeMg ?? 0) || (a.quantity ?? 99) - (b.quantity ?? 99) || a.priceUsd - b.priceUsd
    );
  }
  return [...byVendor.values()].sort((a, b) => a.rank - b.rank || a.vendorName.localeCompare(b.vendorName));
}

/** The product page to send a reader to for a given pack. */
export function packUrl(row: OfferRow, variant: Variant, compound: ShopCompound): string {
  const list = OFFERS_BY_COMPOUND.get(compound.slug) ?? [];
  const hit = list.find((o) => o.vendorSlug === row.vendorSlug && o.variants.some((v) => v.sizeMg === variant.sizeMg && v.priceUsd === variant.priceUsd));
  return hit?.productUrl ?? row.productUrl;
}

/** Price per mg for a variant, or null when the size is unknown. */
export function perMg(v: Variant): number | null {
  if (!v.sizeMg || !v.quantity) return null;
  return v.priceUsd / (v.sizeMg * v.quantity);
}

export function money(n: number, currency: "USD" | "AUD" = "USD"): string {
  const s = n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return currency === "AUD" ? `A$${s}` : `$${s}`;
}

export function mg(n: number): string {
  return `${Number.isInteger(n) ? n : n.toFixed(1)} mg`;
}

/** Offers grouped by compound for a vendor's catalog page. */
export function vendorCatalog(vendor: ShopVendor): { compound: ShopCompound; offers: Offer[] }[] {
  const list = OFFERS_BY_VENDOR.get(vendor.slug) ?? [];
  const groups = new Map<string, Offer[]>();
  for (const o of list) {
    if (!groups.has(o.compoundSlug)) groups.set(o.compoundSlug, []);
    groups.get(o.compoundSlug)!.push(o);
  }
  return [...groups.entries()]
    .map(([slug, offers]) => ({ compound: COMPOUND_BY_SLUG.get(slug)!, offers }))
    .filter((g) => g.compound)
    .sort((a, b) => a.compound.name.localeCompare(b.compound.name));
}

/** The one-line trust statement under a vendor's name. */
export function trustLine(v: ShopVendor): string {
  const parts: string[] = [];
  if (v.independentlyTested && v.labs?.length) parts.push(`Third-party tested by ${v.labs.slice(0, 2).join(" and ")}`);
  else if (v.independentlyTested) parts.push("Third-party tested");
  if (v.coaArchive && v.coaCount) parts.push(`${v.coaCount} public COAs`);
  else if (v.coaArchive) parts.push("Public COA archive");
  if (v.country) parts.push(`Ships from ${v.country === "United States" ? "the US" : v.country}`);
  return parts.join(" · ");
}

export function topCompounds(n: number): ShopCompound[] {
  return SHOP_COMPOUNDS.filter((c) => c.kind === "compound").slice(0, n);
}

export interface ShopSearchRow {
  slug: string;
  name: string;
  blurb: string;
  category: string;
  status: string;
  href: string;
}

export function shopSearchRows(): ShopSearchRow[] {
  return SHOP_COMPOUNDS.map((c) => ({
    slug: c.slug,
    name: c.name,
    blurb: c.kind === "blend" ? "Blend" : c.kind === "essential" ? "Essential" : "",
    category: `${c.vendorCount} vendor${c.vendorCount === 1 ? "" : "s"}`,
    status: c.kind,
    href: shopHref(c.slug),
  }));
}
